(async function () {
  // ─── Load Data ───────────────────────────────────────────────────────
  const raw = await d3.csv("data/stock-descriptions.csv");

  const data = raw.map(function (d) {
    return {
      ticker: d.ticker,
      sector: d.sector,
      name: d["full name"],
      marketCap: d.marketCap !== "" ? +d.marketCap : null,
      country: d.country || null,
      website: d.website || null,
      isETF: d.sector === "ETF"
    };
  });

  // ─── Dimensions ──────────────────────────────────────────────────────
  var chartContainer = document.getElementById("chart-container");
  var width = chartContainer.clientWidth;
  var height = chartContainer.clientHeight;

  // ─── Scales ──────────────────────────────────────────────────────────
  var marketCaps = data.filter(function (d) { return d.marketCap; }).map(function (d) { return d.marketCap; });

  var sizeScale = d3.scaleSqrt()
    .domain([d3.min(marketCaps), d3.max(marketCaps)])
    .range([14, 60]);

  var defaultETFRadius = 16;

  function getRadius(d) {
    return d.marketCap ? sizeScale(d.marketCap) : defaultETFRadius;
  }

  var sectors = Array.from(new Set(data.map(function (d) { return d.sector; })));

  var sectorColors = [
    "#4e79a7", "#f28e2b", "#e15759", "#76b7b2", "#59a14f",
    "#edc948", "#b07aa1", "#ff9da7", "#9c755f", "#bab0ac"
  ];

  var colorScale = d3.scaleOrdinal()
    .domain(sectors)
    .range(sectorColors);

  // ─── Sector cluster positions (arranged in a grid-like pattern) ─────
  var sectorPositions = {};
  var numSectors = sectors.length;
  // Arrange sectors in a roughly circular layout centered in the chart
  var clusterRadius = Math.min(width, height) * 0.25;
  sectors.forEach(function (sector, i) {
    var angle = (2 * Math.PI / numSectors) * i - Math.PI / 2;
    sectorPositions[sector] = {
      x: width / 2 + Math.cos(angle) * clusterRadius,
      y: height / 2 + Math.sin(angle) * clusterRadius
    };
  });

  // ─── SVG ─────────────────────────────────────────────────────────────
  var svg = d3.select("#chart-container")
    .append("svg")
    .attr("width", width)
    .attr("height", height);

  // ─── Tooltip ─────────────────────────────────────────────────────────
  var tooltip = d3.select("body")
    .append("div")
    .attr("class", "tooltip")
    .style("opacity", 0);

  // ─── Force Simulation ────────────────────────────────────────────────
  var simulation = d3.forceSimulation(data)
    .force("x", d3.forceX(function (d) { return sectorPositions[d.sector].x; }).strength(0.6))
    .force("y", d3.forceY(function (d) { return sectorPositions[d.sector].y; }).strength(0.6))
    .force("collide", d3.forceCollide(function (d) { return getRadius(d) + 2; }).iterations(3))
    .force("center", d3.forceCenter(width / 2, height / 2).strength(0.05))
    .on("tick", ticked);

  // Run simulation to completion synchronously for stable layout
  simulation.alpha(1).restart();
  for (var i = 0; i < 300; i++) simulation.tick();
  simulation.stop();

  // Clamp positions to keep bubbles within bounds
  data.forEach(function (d) {
    var r = getRadius(d);
    d.x = Math.max(r, Math.min(width - r, d.x));
    d.y = Math.max(r, Math.min(height - r, d.y));
  });

  // ─── Draw Bubbles ────────────────────────────────────────────────────
  var nodes = svg.selectAll("g.node")
    .data(data)
    .enter()
    .append("g")
    .attr("class", "node")
    .attr("transform", function (d) { return "translate(" + d.x + "," + d.y + ")"; });

  nodes.append("circle")
    .attr("r", function (d) { return getRadius(d); })
    .attr("fill", function (d) { return colorScale(d.sector); })
    .attr("opacity", 0.88);

  nodes.append("text")
    .text(function (d) { return d.ticker; })
    .attr("text-anchor", "middle")
    .attr("dy", "0.35em")
    .style("font-size", function (d) {
      var r = getRadius(d);
      var len = d.ticker.length;
      return Math.max(7, Math.min(14, r * 1.4 / (len * 0.55))) + "px";
    });

  // ─── Tooltip Events ──────────────────────────────────────────────────
  nodes
    .on("mouseover", function (event, d) {
      if (d.isETF) return;
      tooltip.transition().duration(150).style("opacity", 1);
      tooltip.html(
        "<strong>" + d.ticker + "</strong><br>" +
        d.name + "<br>" +
        "<span class='sector-badge'>" + d.sector + "</span>"
      )
        .style("left", (event.pageX + 14) + "px")
        .style("top", (event.pageY - 16) + "px");
    })
    .on("mousemove", function (event, d) {
      if (d.isETF) return;
      tooltip
        .style("left", (event.pageX + 14) + "px")
        .style("top", (event.pageY - 16) + "px");
    })
    .on("mouseout", function () {
      tooltip.transition().duration(200).style("opacity", 0);
    });

  // ─── Click: Bubble → Table ───────────────────────────────────────────
  nodes.on("click", function (event, d) {
    selectStock(d.ticker);
  });

  function ticked() {
    nodes.attr("transform", function (d) { return "translate(" + d.x + "," + d.y + ")"; });
  }

  // ─── Legend ──────────────────────────────────────────────────────────
  var legendX = 14;
  var legendY = 14;

  var legendGroup = svg.append("g")
    .attr("class", "legend-group")
    .attr("transform", "translate(" + legendX + "," + legendY + ")");

  var legendItems = legendGroup.selectAll(".legend-item")
    .data(sectors)
    .enter()
    .append("g")
    .attr("class", "legend-item")
    .attr("transform", function (d, i) { return "translate(0," + (i * 22) + ")"; });

  legendItems.append("rect")
    .attr("width", 13)
    .attr("height", 13)
    .attr("rx", 3)
    .attr("fill", function (d) { return colorScale(d); })
    .attr("opacity", 0.88);

  legendItems.append("text")
    .attr("x", 19)
    .attr("y", 10.5)
    .text(function (d) { return d; });

  // ─── Data Table ──────────────────────────────────────────────────────
  function formatMarketCap(val) {
    if (val == null) return "N/A";
    if (val >= 1e12) return (val / 1e12).toFixed(2) + "T";
    if (val >= 1e9) return (val / 1e9).toFixed(2) + "B";
    if (val >= 1e6) return (val / 1e6).toFixed(2) + "M";
    return val.toFixed(0);
  }

  var table = d3.select("#table-container")
    .append("table")
    .attr("class", "data-table");

  var thead = table.append("thead");
  var tbody = table.append("tbody");

  var columns = [
    { key: "ticker", label: "Ticker" },
    { key: "name", label: "Company Name" },
    { key: "sector", label: "Sector" },
    { key: "marketCap", label: "Market Cap" }
  ];

  thead.append("tr")
    .selectAll("th")
    .data(columns)
    .enter()
    .append("th")
    .text(function (d) { return d.label; });

  var rows = tbody.selectAll("tr")
    .data(data)
    .enter()
    .append("tr")
    .attr("data-ticker", function (d) { return d.ticker; });

  rows.selectAll("td")
    .data(function (d) {
      return [
        d.ticker,
        d.name,
        d.sector,
        formatMarketCap(d.marketCap)
      ];
    })
    .enter()
    .append("td")
    .text(function (d) { return d; })
    .attr("title", function (d) { return d; });

  // ─── Click: Table → Bubble ───────────────────────────────────────────
  rows.on("click", function (event, d) {
    selectStock(d.ticker);
  });

  // ─── Shared Selection Logic ──────────────────────────────────────────
  var selectedTicker = null;

  function selectStock(ticker) {
    // Toggle if clicking the same stock
    if (selectedTicker === ticker) {
      selectedTicker = null;
      d3.selectAll(".node circle").classed("selected", false);
      d3.selectAll("tbody tr").classed("highlighted", false);
      return;
    }

    selectedTicker = ticker;

    // Highlight bubble
    d3.selectAll(".node circle").classed("selected", false);
    d3.selectAll(".node")
      .filter(function (d) { return d.ticker === ticker; })
      .select("circle")
      .classed("selected", true);

    // Highlight table row
    d3.selectAll("tbody tr").classed("highlighted", false);
    var row = document.querySelector('tr[data-ticker="' + ticker + '"]');
    if (row) {
      d3.select(row).classed("highlighted", true);
      row.scrollIntoView({ behavior: "smooth", block: "center" });
    }
  }

})();
